// Get the HTTP response - n8n API returns { data: [...workflows...] }
const httpResponse = $input.first().json;

// Extract workflows array from the API response
const allWorkflows = httpResponse.data || [];

// Define tag categories for folder organization
const tagCategories = ['Prod', 'Test', 'New', 'Temp', 'IMP'];
const excludeTag = 'STOP GIT';

// Filter and process workflows
const filteredWorkflows = [];

for (const workflow of allWorkflows) {
  const workflowTags = workflow.tags || [];

  // Check if workflow has STOP GIT tag (case insensitive)
  const hasExcludeTag = workflowTags.some(tag => 
    tag.name && tag.name.toUpperCase() === excludeTag.toUpperCase()
  );

  // Skip if has exclude tag
  if (hasExcludeTag) {
    continue;
  }

  // Determine folder based on first matching tag
  let folderName = 'Uncategorized';
  for (const tag of workflowTags) {
    if (tag.name && tagCategories.includes(tag.name)) {
      folderName = tag.name;
      break;
    }
  }

  // Prepare workflow data - each workflow becomes its own item
  filteredWorkflows.push({
    json: {
      id: workflow.id,
      name: workflow.name,
      active: workflow.active,
      tags: workflowTags,
      folderName: folderName,
      workflowData: workflow,
      updatedAt: workflow.updatedAt || new Date().toISOString()
    }
  });
}

// Return all filtered workflows as separate items
return filteredWorkflows;

// Pure JS hash function (FNV-1a) - no require('crypto') needed
function fnv1aHash(str) {
  let hash = 2166136261;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash * 16777619) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

// CRITICAL: $input.all() here contains GitHub repo API response data
// because Check if GitHub Repo Exists HTTP node replaces the item data.
// We must reference the ORIGINAL workflow data from the Filter node.
const originalWorkflows = $('Filter Workflows (Exclude STOP GIT)').all();

// Initialize tracking
const backupSession = {
  timestamp: new Date().toISOString(),
  timestampIST: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
  totalWorkflows: originalWorkflows.length,
  newWorkflows: [],
  modifiedWorkflows: [],
  unchangedWorkflows: [],
  errorWorkflows: []
};

// Process each workflow and add hash
const processedWorkflows = originalWorkflows.map(item => {
  const workflow = item.json;

  // Create deterministic JSON string for hashing
  const workflowJSON = JSON.stringify(workflow.workflowData, null, 2);

  // Calculate hash using pure JS FNV-1a
  const hash = fnv1aHash(workflowJSON);

  return {
    json: {
      ...workflow,
      workflowJSON: workflowJSON,
      workflowHash: hash,
      fileName: `${workflow.name.replace(/[^a-zA-Z0-9-_]/g, '_')}.json`,
      filePath: `workflows/${workflow.folderName}/${workflow.name.replace(/[^a-zA-Z0-9-_]/g, '_')}.json`,
      backupSession: backupSession
    }
  };
});

return processedWorkflows;

// Pure JS hash function (FNV-1a) - same as Initialize Backup Session
function fnv1aHash(str) {
  let hash = 2166136261;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash * 16777619) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

// Get current workflow data from the batch loop
const currentWorkflow = $('Process Each Workflow').item.json;
const existingFileData = $('Get Existing Workflow File').item.json;

// Decode existing file content from GitHub (base64)
// Buffer.from IS available in n8n Code nodes
const existingContent = Buffer.from(existingFileData.content, 'base64').toString('utf-8');

// Calculate hash of existing content using pure JS
const existingHash = fnv1aHash(existingContent);

// Compare hashes
const hasChanged = currentWorkflow.workflowHash !== existingHash;

return [{
  json: {
    ...currentWorkflow,
    existingFileSHA: existingFileData.sha,
    existingHash: existingHash,
    hasChanged: hasChanged,
    changeStatus: hasChanged ? 'MODIFIED' : 'UNCHANGED'
  }
}];

// Get workflow data from the SplitInBatches node (original workflow data)
// NOT from $input which may contain HTTP error response on the NEW workflow path
const item = $('Process Each Workflow').item.json;

// Also check if we have Compare Hashes data (MODIFIED path)
// On NEW path, $input comes from File Exists on GitHub? FALSE output
let existingFileSHA = null;
try {
  const compareData = $input.first().json;
  existingFileSHA = compareData.existingFileSHA || null;
} catch (e) {
  existingFileSHA = null;
}

// Determine change status
const changeStatus = item.changeStatus || (existingFileSHA ? 'MODIFIED' : 'NEW');

// Base64 encode the workflow JSON
// Buffer.from IS available in n8n Code nodes (confirmed)
const base64Content = Buffer.from(item.workflowJSON).toString('base64');

// Build the request body for GitHub API
const requestBody = {
  message: `[${changeStatus}] ${item.name} - ${item.backupSession.timestampIST}`,
  content: base64Content,
  branch: 'main',
  committer: {
    name: 'n8n Atul',
    email: 'gupta.atulgupta13@gmail.com'
  }
};

// Add SHA only if updating existing file (MODIFIED workflows)
if (existingFileSHA) {
  requestBody.sha = existingFileSHA;
}

return [{
  json: {
    ...item,
    changeStatus: changeStatus,
    githubRequestBody: JSON.stringify(requestBody)
  }
}];

// Get the ORIGINAL workflow data from the batch loop, not the HTTP upload response
const workflow = $('Process Each Workflow').item.json;
const uploadResponse = $('Upload Workflow to GitHub').item.json;

// Track this change
const changeRecord = {
  workflowName: workflow.name,
  status: workflow.changeStatus || 'UPLOADED',
  filePath: workflow.filePath,
  commitSHA: uploadResponse.commit?.sha || 'unknown',
  timestamp: workflow.backupSession.timestampIST
};

return [{
  json: {
    ...workflow,
    uploadSuccess: true,
    changeRecord: changeRecord
  }
}];

const allResults = $input.all();

// Count statistics
let newCount = 0;
let modifiedCount = 0;
let unchangedCount = 0;
let errorCount = 0;

const changeDetails = [];

for (const item of allResults) {
  const workflow = item.json;

  if (workflow.changeStatus === 'NEW') {
    newCount++;
    changeDetails.push(`NEW: ${workflow.name}`);
  } else if (workflow.changeStatus === 'MODIFIED') {
    modifiedCount++;
    changeDetails.push(`MODIFIED: ${workflow.name}`);
  } else if (workflow.changeStatus === 'UNCHANGED') {
    unchangedCount++;
  }
}

const totalProcessed = newCount + modifiedCount + unchangedCount;
const totalUploaded = newCount + modifiedCount;

// Generate summary message
let summaryMessage = `[Automated Backup] `;

if (totalUploaded === 0) {
  summaryMessage += `No changes detected - ${totalProcessed} workflows checked`;
} else {
  const parts = [];
  if (newCount > 0) parts.push(`Added ${newCount} new workflow${newCount > 1 ? 's' : ''}`);
  if (modifiedCount > 0) parts.push(`Updated ${modifiedCount} workflow${modifiedCount > 1 ? 's' : ''}`);
  summaryMessage += parts.join(', ');
  summaryMessage += ` - ${new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })}`;
}

return [{
  json: {
    summary: {
      timestamp: new Date().toISOString(),
      timestampIST: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
      totalWorkflows: totalProcessed,
      newWorkflows: newCount,
      modifiedWorkflows: modifiedCount,
      unchangedWorkflows: unchangedCount,
      totalUploaded: totalUploaded,
      summaryMessage: summaryMessage,
      changeDetails: changeDetails
    }
  }
}];

